-- M26: graphic content operations and safe user lifecycle. Existing records are preserved in place.
alter table public.ideas add column if not exists content_type text;
alter table public.ideas drop constraint if exists ideas_content_type_check;
alter table public.ideas add constraint ideas_content_type_check check(content_type is null or content_type in('owner_ip','product_education','customer_case','industry_knowledge','company_culture','event','conversion','other'));
alter table public.ideas drop constraint if exists ideas_content_format_check;
alter table public.ideas add constraint ideas_content_format_check check(content_format is null or content_format in('q_and_a','talking_head','skit','onsite_video','product_demo','podcast','voice_over','event','single_image','carousel','long_form_post','graphic_other'));
alter table public.contents add column if not exists content_type text check(content_type is null or content_type in('owner_ip','product_education','customer_case','industry_knowledge','company_culture','event','conversion','other'));
alter table public.contents add column if not exists content_format text check(content_format is null or content_format in('q_and_a','talking_head','skit','onsite_video','product_demo','podcast','voice_over','event','single_image','carousel','long_form_post','graphic_other'));
update public.ideas set content_type='owner_ip' where content_type is null and exists(select 1 from public.content_categories cc where cc.id=ideas.category_id and lower(replace(cc.name,' ','')) in('老板ip','ownerip'));
update public.contents c set content_type=i.content_type,content_format=i.content_format from public.ideas i where i.id=c.source_idea_id and (c.content_type is null or c.content_format is null);
create or replace function public.inherit_content_taxonomy() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.source_idea_id is not null then select coalesce(new.content_type,i.content_type),coalesce(new.content_format,i.content_format) into new.content_type,new.content_format from public.ideas i where i.id=new.source_idea_id;end if;return new;end $$;
drop trigger if exists contents_inherit_taxonomy on public.contents;create trigger contents_inherit_taxonomy before insert or update of source_idea_id,content_type,content_format on public.contents for each row execute function public.inherit_content_taxonomy();
create or replace function public.save_idea_submission_v2(target_idea_id uuid,target_workspace_id uuid,target_client_id uuid,target_title text,target_source_url text,target_original_topic text,target_original_hook text,target_why_it_works text,target_our_angle text,target_category_id uuid,target_suggested_format text,target_priority text,target_provider_team_member_id uuid,target_notes text,target_reference_ids uuid[],target_tag_names text[],target_contributors jsonb,target_planned_date date,target_source_platform text,target_raw_content text,target_content_format text,target_content_type text) returns uuid language plpgsql security definer set search_path='' as $$ declare saved uuid;t text:=nullif(lower(btrim(target_content_type)),'');begin if t is not null and t not in('owner_ip','product_education','customer_case','industry_knowledge','company_culture','event','conversion','other') then raise exception 'Unsupported Content type';end if;saved:=public.save_idea_submission(target_idea_id,target_workspace_id,target_client_id,target_title,target_source_url,target_original_topic,target_original_hook,target_why_it_works,target_our_angle,target_category_id,target_suggested_format,target_priority,target_provider_team_member_id,target_notes,target_reference_ids,target_tag_names,target_contributors,target_planned_date,target_source_platform,target_raw_content,target_content_format);update public.ideas set content_type=t where id=saved and public.can_edit_idea_submission(saved);return saved;end $$;
create table public.graphic_content_packs(id uuid primary key default gen_random_uuid(),content_id uuid not null unique references public.contents(id) on delete restrict,headline text,cover_copy text,cta text,caption text,hashtags text[],design_notes text,reference_links text[],asset_notes text,platforms text[],review_status text not null default 'draft' check(review_status in('draft','in_review','revision_required','approved')),single_image_core_info text,single_image_supporting_info text,single_image_visual_note text,pages jsonb not null default '[]'::jsonb check(jsonb_typeof(pages)='array'),created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create trigger graphic_content_packs_updated before update on public.graphic_content_packs for each row execute function public.set_updated_at();alter table public.graphic_content_packs enable row level security;revoke all on public.graphic_content_packs from anon,authenticated;grant select on public.graphic_content_packs to authenticated;create policy "Authorized internal users view Graphic Packs" on public.graphic_content_packs for select to authenticated using(public.can_view_content(content_id));
create table public.customer_case_profiles(id uuid primary key default gen_random_uuid(),content_id uuid not null unique references public.contents(id) on delete restrict,case_client_id uuid references public.clients(id) on delete restrict,industry text,location text,product_solution text,client_highlights text,lksoft_solution text,cta text,needs_client_approval boolean not null default false,client_approval_status text check(client_approval_status is null or client_approval_status in('pending','approved','revision_required')),created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create trigger customer_case_profiles_updated before update on public.customer_case_profiles for each row execute function public.set_updated_at();alter table public.customer_case_profiles enable row level security;revoke all on public.customer_case_profiles from anon,authenticated;grant select on public.customer_case_profiles to authenticated;create policy "Authorized internal users view Customer Cases" on public.customer_case_profiles for select to authenticated using(public.can_view_content(content_id));
create or replace function public.save_graphic_content_pack(target_content_id uuid,target_payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare c public.contents%rowtype;s uuid;p jsonb:=coalesce(target_payload->'pages','[]'::jsonb);begin select * into c from public.contents where id=target_content_id for update;if c.id is null or c.content_format not in('single_image','carousel','long_form_post','graphic_other') then raise exception 'Graphic Content is required';end if;if not public.can_manage_content_assignments(c.id) then raise exception 'Graphic Content access denied';end if;if jsonb_typeof(p)<>'array' then raise exception 'Graphic pages must be an array';end if;insert into public.graphic_content_packs(content_id,headline,cover_copy,cta,caption,hashtags,design_notes,reference_links,asset_notes,platforms,review_status,single_image_core_info,single_image_supporting_info,single_image_visual_note,pages,created_by) values(c.id,nullif(btrim(target_payload->>'headline'),''),nullif(btrim(target_payload->>'cover_copy'),''),nullif(btrim(target_payload->>'cta'),''),nullif(btrim(target_payload->>'caption'),''),coalesce(array(select jsonb_array_elements_text(coalesce(target_payload->'hashtags','[]'::jsonb))),'{}'),nullif(btrim(target_payload->>'design_notes'),''),coalesce(array(select jsonb_array_elements_text(coalesce(target_payload->'reference_links','[]'::jsonb))),'{}'),nullif(btrim(target_payload->>'asset_notes'),''),coalesce(array(select jsonb_array_elements_text(coalesce(target_payload->'platforms','[]'::jsonb))),'{}'),coalesce(nullif(target_payload->>'review_status',''),'draft'),nullif(btrim(target_payload->>'single_image_core_info'),''),nullif(btrim(target_payload->>'single_image_supporting_info'),''),nullif(btrim(target_payload->>'single_image_visual_note'),''),p,auth.uid()) on conflict(content_id) do update set headline=excluded.headline,cover_copy=excluded.cover_copy,cta=excluded.cta,caption=excluded.caption,hashtags=excluded.hashtags,design_notes=excluded.design_notes,reference_links=excluded.reference_links,asset_notes=excluded.asset_notes,platforms=excluded.platforms,review_status=excluded.review_status,single_image_core_info=excluded.single_image_core_info,single_image_supporting_info=excluded.single_image_supporting_info,single_image_visual_note=excluded.single_image_visual_note,pages=excluded.pages returning id into s;return s;end $$;
create or replace function public.save_customer_case_profile(target_content_id uuid,target_payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare c public.contents%rowtype;s uuid;cc uuid:=nullif(target_payload->>'case_client_id','')::uuid;begin select * into c from public.contents where id=target_content_id for update;if c.id is null or c.content_type<>'customer_case' then raise exception 'Customer Case Content is required';end if;if not public.can_manage_content_assignments(c.id) then raise exception 'Customer Case access denied';end if;if cc is not null and not exists(select 1 from public.clients x where x.id=cc and x.workspace_id=c.workspace_id) then raise exception 'Customer Case Client is outside this Workspace';end if;insert into public.customer_case_profiles(content_id,case_client_id,industry,location,product_solution,client_highlights,lksoft_solution,cta,needs_client_approval,client_approval_status,created_by) values(c.id,cc,nullif(btrim(target_payload->>'industry'),''),nullif(btrim(target_payload->>'location'),''),nullif(btrim(target_payload->>'product_solution'),''),nullif(btrim(target_payload->>'client_highlights'),''),nullif(btrim(target_payload->>'lksoft_solution'),''),nullif(btrim(target_payload->>'cta'),''),coalesce((target_payload->>'needs_client_approval')::boolean,false),nullif(target_payload->>'client_approval_status',''),auth.uid()) on conflict(content_id) do update set case_client_id=excluded.case_client_id,industry=excluded.industry,location=excluded.location,product_solution=excluded.product_solution,client_highlights=excluded.client_highlights,lksoft_solution=excluded.lksoft_solution,cta=excluded.cta,needs_client_approval=excluded.needs_client_approval,client_approval_status=excluded.client_approval_status returning id into s;return s;end $$;
alter table public.contents drop constraint if exists contents_current_status_check;alter table public.contents add constraint contents_current_status_check check(current_status in('draft','ready_to_shoot','shooting','shot_awaiting_edit','editing','first_cut_submitted','internal_review','revision_required','client_review','approved','ready_for_publishing','analytics_tracking','completed','cancelled','graphic_in_production','graphic_review','published'));
alter table public.workflow_events drop constraint if exists workflow_events_event_type_check;alter table public.workflow_events add constraint workflow_events_event_type_check check(event_type in('marked_ready_to_shoot','shoot_started','shoot_completed','editing_started','first_cut_submitted','review_started','revision_requested','revision_started','revision_submitted','sent_to_client_review','approval_recorded','final_media_submitted','final_approved','approval_overridden','publication_prepared','publication_scheduled','publication_published','publication_failed','publication_cancelled','analytics_snapshot_added','content_completed','graphic_production_started','graphic_review_submitted','graphic_revision_requested','graphic_approved','graphic_publish_scheduled','graphic_published','graphic_completed'));
create or replace function public.perform_graphic_workflow_action(target_content_id uuid,target_action text,expected_from_state text,target_note text default null) returns table(event_id uuid,new_status text,occurred_at timestamptz) language plpgsql security definer set search_path='' as $$ declare c public.contents%rowtype;n text;e text;s uuid;ok boolean:=false;t timestamptz:=now();begin select * into c from public.contents where id=target_content_id for update;if c.id is null or c.content_format not in('single_image','carousel','long_form_post','graphic_other') then raise exception 'Graphic Content is required';end if;if c.current_status is distinct from expected_from_state then raise exception 'Stale Workflow Action';end if;case target_action when 'start_production' then if c.current_status<>'draft' then raise exception 'Illegal Graphic transition';end if;n:='graphic_in_production';e:='graphic_production_started';ok:=public.can_manage_content_assignments(c.id) or public.has_active_content_assignment(c.id,'copywriter') or public.has_active_content_assignment(c.id,'designer');when 'submit_review' then if c.current_status not in('graphic_in_production','revision_required') then raise exception 'Illegal Graphic transition';end if;n:='graphic_review';e:='graphic_review_submitted';ok:=public.can_manage_content_assignments(c.id) or public.has_active_content_assignment(c.id,'copywriter') or public.has_active_content_assignment(c.id,'designer');when 'request_revision' then if c.current_status<>'graphic_review' then raise exception 'Illegal Graphic transition';end if;n:='revision_required';e:='graphic_revision_requested';ok:=public.has_active_content_assignment(c.id,'reviewer');when 'approve' then if c.current_status<>'graphic_review' then raise exception 'Illegal Graphic transition';end if;n:='ready_for_publishing';e:='graphic_approved';ok:=public.has_active_content_assignment(c.id,'reviewer');when 'schedule_publishing' then if c.current_status<>'ready_for_publishing' then raise exception 'Illegal Graphic transition';end if;n:=c.current_status;e:='graphic_publish_scheduled';ok:=public.has_workspace_role(c.workspace_id,'publisher_marketing') and public.has_active_content_assignment(c.id,'publisher');when 'mark_published' then if c.current_status<>'ready_for_publishing' then raise exception 'Illegal Graphic transition';end if;n:='published';e:='graphic_published';ok:=public.has_workspace_role(c.workspace_id,'publisher_marketing') and public.has_active_content_assignment(c.id,'publisher');when 'complete' then if c.current_status<>'published' then raise exception 'Illegal Graphic transition';end if;n:='completed';e:='graphic_completed';ok:=public.can_manage_content_assignments(c.id);else raise exception 'Unsupported Graphic Workflow Action';end case;if not ok then raise exception 'Graphic Workflow permission or assignment denied';end if;perform set_config('contentos.workflow_action','allowed',true);update public.contents set current_status=n where id=c.id;perform set_config('contentos.workflow_action','',true);insert into public.workflow_events(workspace_id,client_id,content_id,actor_user_id,event_type,from_state,to_state,occurred_at,notes) values(c.workspace_id,c.client_id,c.id,auth.uid(),e,c.current_status,n,t,nullif(btrim(target_note),'')) returning id into s;return query select s,n,t;end $$;
insert into public.contribution_roles(workspace_id,code,name,sort_order) select id,'copywriter','Copywriter',45 from public.workspaces on conflict(workspace_id,code) do update set is_active=true;insert into public.contribution_roles(workspace_id,code,name,sort_order) select id,'designer','Designer',55 from public.workspaces on conflict(workspace_id,code) do update set is_active=true;
create table public.content_attribution_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),content_id uuid not null references public.contents(id),idea_id uuid not null references public.ideas(id),actor_user_id uuid not null references public.user_profiles(id),from_team_member_id uuid references public.team_members(id),to_team_member_id uuid references public.team_members(id),occurred_at timestamptz not null default now());create trigger content_attribution_events_immutable before update or delete on public.content_attribution_events for each row execute function public.prevent_immutable_history_mutation();alter table public.content_attribution_events enable row level security;revoke all on public.content_attribution_events from anon,authenticated;grant select on public.content_attribution_events to authenticated;create policy "Authorized users view attribution audit" on public.content_attribution_events for select to authenticated using(public.can_view_content(content_id));
create or replace function public.set_content_idea_provider(target_content_id uuid,target_team_member_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare c public.contents%rowtype;i public.ideas%rowtype;old uuid;begin select * into c from public.contents where id=target_content_id for update;if c.id is null or c.source_idea_id is null then raise exception 'Content has no source Idea';end if;if not(public.has_workspace_role(c.workspace_id,'super_admin') or public.has_workspace_role(c.workspace_id,'publisher_marketing')) then raise exception 'Only Super Admin or Marketing can change Idea provider';end if;if target_team_member_id is not null and not exists(select 1 from public.team_members where id=target_team_member_id and workspace_id=c.workspace_id and status='active') then raise exception 'Idea provider is unavailable';end if;select * into i from public.ideas where id=c.source_idea_id for update;old:=i.idea_provider_team_member_id;if old is not distinct from target_team_member_id then return;end if;update public.ideas set idea_provider_team_member_id=target_team_member_id where id=i.id;insert into public.content_attribution_events(workspace_id,content_id,idea_id,actor_user_id,from_team_member_id,to_team_member_id) values(c.workspace_id,c.id,i.id,auth.uid(),old,target_team_member_id);end $$;
alter table public.team_members add column if not exists is_test_account boolean not null default false;
create table public.user_lifecycle_audits(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),actor_user_id uuid not null references public.user_profiles(id),subject_team_member_id uuid,subject_auth_user_id uuid,subject_name text not null,action text not null check(action in('deactivated','reactivated','hard_deleted')),occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);create trigger user_lifecycle_audits_immutable before update or delete on public.user_lifecycle_audits for each row execute function public.prevent_immutable_history_mutation();alter table public.user_lifecycle_audits enable row level security;revoke all on public.user_lifecycle_audits from anon,authenticated;grant select on public.user_lifecycle_audits to authenticated;create policy "Super Admins view lifecycle audits" on public.user_lifecycle_audits for select to authenticated using(public.is_workspace_super_admin(workspace_id));
create or replace function public.set_team_member_access(target_team_member_id uuid,make_active boolean) returns void language plpgsql security definer set search_path='' as $$ declare m public.team_members%rowtype;wm public.workspace_members%rowtype;sr uuid;n int;begin select * into m from public.team_members where id=target_team_member_id for update;if m.id is null or not public.is_workspace_super_admin(m.workspace_id) then raise exception 'Only Super Admin can manage access';end if;if m.auth_user_id is null then raise exception 'This Team Member has no login access';end if;select * into wm from public.workspace_members where workspace_id=m.workspace_id and user_profile_id=m.auth_user_id for update;if wm.id is null then raise exception 'Workspace membership not found';end if;select id into sr from public.roles where workspace_id=m.workspace_id and code='super_admin';if not make_active and exists(select 1 from public.workspace_member_roles where workspace_member_id=wm.id and role_id=sr) then select count(*) into n from public.workspace_members x join public.workspace_member_roles r on r.workspace_member_id=x.id where x.workspace_id=m.workspace_id and x.status='active' and r.role_id=sr;if n<=1 then raise exception 'Cannot deactivate the last Super Admin';end if;end if;update public.workspace_members set status=case when make_active then 'active' else 'deactivated' end,deactivated_at=case when make_active then null else now() end where id=wm.id;update public.user_profiles set status=case when make_active then 'active' else 'deactivated' end,deactivated_at=case when make_active then null else now() end where id=m.auth_user_id;update public.team_members set status=case when make_active then 'active' else 'inactive' end where id=m.id;insert into public.user_lifecycle_audits(workspace_id,actor_user_id,subject_team_member_id,subject_auth_user_id,subject_name,action) values(m.workspace_id,auth.uid(),m.id,m.auth_user_id,m.name,case when make_active then 'reactivated' else 'deactivated' end);end $$;
create or replace function public.mark_test_team_member(target_team_member_id uuid,confirmation text) returns void language plpgsql security definer set search_path='' as $$ declare m public.team_members%rowtype;begin select * into m from public.team_members where id=target_team_member_id for update;if m.id is null or not public.is_workspace_super_admin(m.workspace_id) then raise exception 'Only Super Admin can mark test users';end if;if confirmation<>m.name or not(lower(m.name) like '%test%' or lower(coalesce(m.email,'')) like '%+test@%' or lower(coalesce(m.email,'')) like '%@example.com') then raise exception 'Only clearly named test accounts can be marked';end if;update public.team_members set is_test_account=true where id=m.id;end $$;
create or replace function public.hard_delete_test_team_member(target_team_member_id uuid,confirmation text) returns void language plpgsql security definer set search_path='' as $$ declare m public.team_members%rowtype;wm public.workspace_members%rowtype;sr uuid;n int;u uuid;begin if confirmation<>'DELETE' then raise exception 'Type DELETE to confirm';end if;select * into m from public.team_members where id=target_team_member_id for update;if m.id is null or not public.is_workspace_super_admin(m.workspace_id) then raise exception 'Only Super Admin can permanently delete test users';end if;if not m.is_test_account or not(lower(m.name) like '%test%' or lower(coalesce(m.email,'')) like '%+test@%' or lower(coalesce(m.email,'')) like '%@example.com') then raise exception 'Only explicitly marked test accounts can be permanently deleted';end if;u:=m.auth_user_id;select * into wm from public.workspace_members where workspace_id=m.workspace_id and user_profile_id=u for update;select id into sr from public.roles where workspace_id=m.workspace_id and code='super_admin';if wm.id is not null and exists(select 1 from public.workspace_member_roles where workspace_member_id=wm.id and role_id=sr) then select count(*) into n from public.workspace_members x join public.workspace_member_roles r on r.workspace_member_id=x.id where x.workspace_id=m.workspace_id and x.status='active' and r.role_id=sr;if n<=1 then raise exception 'Cannot delete the last Super Admin';end if;end if;if exists(select 1 from public.ideas where idea_provider_team_member_id=m.id or created_by=u or owner_user_id=u) or exists(select 1 from public.contents where owner_team_member_id=m.id or created_by=u or current_owner_user_id=u) or exists(select 1 from public.content_contributors where team_member_id=m.id or user_profile_id=u) or exists(select 1 from public.workflow_events where actor_user_id=u) or exists(select 1 from public.activity_logs where actor_user_id=u) or exists(select 1 from public.tasks where assigned_team_member_id=m.id or created_by=u) or exists(select 1 from public.publications where assigned_publisher_user_id=u or created_by=u) or exists(select 1 from public.revision_requests where requested_by=u) or exists(select 1 from public.team_report_events where team_member_id=m.id or actor_user_id=u) then raise exception 'This member has business history and cannot be permanently deleted. Deactivate access instead.';end if;insert into public.user_lifecycle_audits(workspace_id,actor_user_id,subject_name,action,metadata) values(m.workspace_id,auth.uid(),m.name,'hard_deleted',jsonb_build_object('team_member_id',m.id,'auth_user_id',u));delete from public.access_requests where linked_team_member_id=m.id or auth_user_id=u;if wm.id is not null then delete from public.client_members where workspace_member_id=wm.id;delete from public.workspace_member_roles where workspace_member_id=wm.id;delete from public.workspace_members where id=wm.id;end if;delete from public.team_members where id=m.id;if u is not null then delete from public.user_profiles where id=u;delete from auth.users where id=u;end if;end $$;
revoke all on function public.save_idea_submission_v2(uuid,uuid,uuid,text,text,text,text,text,text,uuid,text,text,uuid,text,uuid[],text[],jsonb,date,text,text,text,text),public.save_graphic_content_pack(uuid,jsonb),public.save_customer_case_profile(uuid,jsonb),public.perform_graphic_workflow_action(uuid,text,text,text),public.set_content_idea_provider(uuid,uuid),public.set_team_member_access(uuid,boolean),public.mark_test_team_member(uuid,text),public.hard_delete_test_team_member(uuid,text) from public,anon;grant execute on function public.save_idea_submission_v2(uuid,uuid,uuid,text,text,text,text,text,text,uuid,text,text,uuid,text,uuid[],text[],jsonb,date,text,text,text,text),public.save_graphic_content_pack(uuid,jsonb),public.save_customer_case_profile(uuid,jsonb),public.perform_graphic_workflow_action(uuid,text,text,text),public.set_content_idea_provider(uuid,uuid),public.set_team_member_access(uuid,boolean),public.mark_test_team_member(uuid,text),public.hard_delete_test_team_member(uuid,text) to authenticated;
-- Preserve immutable access review history while allowing a zero-history test Auth identity to be removed.
create or replace function public.preserve_access_audit_fk_nulling() returns trigger language plpgsql set search_path='' as $$ begin if old.access_request_id is distinct from new.access_request_id and new.access_request_id is null and old.subject_auth_user_id is not distinct from new.subject_auth_user_id then return new;end if;if old.subject_auth_user_id is distinct from new.subject_auth_user_id and new.subject_auth_user_id is null and old.access_request_id is not distinct from new.access_request_id then return new;end if;raise exception 'Access Request audit history is immutable';end $$;
drop trigger if exists access_request_audits_immutable on public.access_request_audits;create trigger access_request_audits_immutable before update or delete on public.access_request_audits for each row execute function public.preserve_access_audit_fk_nulling();
alter table public.access_request_audits alter column access_request_id drop not null;alter table public.access_request_audits alter column subject_auth_user_id drop not null;
alter table public.access_request_audits drop constraint if exists access_request_audits_access_request_id_fkey;alter table public.access_request_audits add constraint access_request_audits_access_request_id_fkey foreign key(access_request_id) references public.access_requests(id) on delete set null;
alter table public.access_request_audits drop constraint if exists access_request_audits_subject_auth_user_id_fkey;alter table public.access_request_audits add constraint access_request_audits_subject_auth_user_id_fkey foreign key(subject_auth_user_id) references auth.users(id) on delete set null;

create or replace function public.assign_content_team_member(target_content_id uuid,target_team_member_id uuid,target_role_code text,target_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare saved uuid;c public.contents%rowtype;m public.team_members%rowtype;role_id uuid;prior uuid;begin select * into c from public.contents where id=target_content_id for update;if c.id is null or not public.can_manage_content_assignments(c.id) then raise exception 'Production assignment access denied';end if;if target_role_code not in('owner','talent','director','shooter','editor','reviewer','publisher','copywriter','designer') then raise exception 'Unsupported production role';end if;if c.content_format in('single_image','carousel','long_form_post','graphic_other') and target_role_code in('talent','director','shooter','editor') then raise exception 'Video roles cannot be assigned to Graphic Content';end if;select * into m from public.team_members where id=target_team_member_id and workspace_id=c.workspace_id and status='active';select id into role_id from public.contribution_roles where workspace_id=c.workspace_id and code=target_role_code and is_active;if m.id is null or role_id is null then raise exception 'Team Member or role unavailable';end if;for prior in select id from public.content_contributors where content_id=c.id and contribution_role_id=role_id and status='active' and team_member_id<>m.id loop update public.content_contributors set status='removed',removed_at=now(),removed_by=auth.uid() where id=prior;end loop;insert into public.content_contributors(content_id,user_profile_id,team_member_id,contribution_role_id,notes,added_by) values(c.id,m.auth_user_id,m.id,role_id,nullif(btrim(target_notes),''),auth.uid()) on conflict(content_id,team_member_id,contribution_role_id) do update set status='active',removed_at=null,removed_by=null,user_profile_id=excluded.user_profile_id,notes=excluded.notes,added_by=auth.uid(),created_at=now() returning id into saved;if target_role_code='owner' then update public.contents set owner_team_member_id=m.id,current_owner_user_id=m.auth_user_id where id=c.id;end if;insert into public.activity_logs(workspace_id,client_id,content_id,actor_user_id,entity_type,entity_id,action,metadata) values(c.workspace_id,c.client_id,c.id,auth.uid(),'content_contributor',saved,'contributor_assigned',jsonb_build_object('team_member_id',m.id,'user_name',m.name,'contribution_role',target_role_code));return saved;end $$;
notify pgrst,'reload schema';